// Why Code: agrégation + calcul de dates sur toutes les lignes, aucun nœud natif unique ne le fait.
const rows = $input.all().map(function (i) { return i.json; }).filter(function (r) { return r.Statut; });
const now = DateTime.now();
const weekAgo = now.minus({ days: 7 });
function when(r) { return DateTime.fromISO(String(r.Date || '')); }
const recent = rows.filter(function (r) { return when(r).isValid && when(r) >= weekAgo; });
const positifs = recent.filter(function (r) { return r.Statut === 'POSITIF'; });
const refus = recent.filter(function (r) { return r.Statut === 'REFUS'; });
// Une ligne EN_ATTENTE est close si un REFUS/POSITIF plus récent existe pour la même entreprise (et le même poste si les deux sont renseignés).
function superseded(r) {
  return rows.some(function (o) {
    return o.Entreprise === r.Entreprise && ['REFUS', 'POSITIF'].indexOf(o.Statut) >= 0 && (!o.Poste || !r.Poste || o.Poste === r.Poste) && when(o).isValid && when(o) >= when(r);
  });
}
const relances = rows.filter(function (r) { return r.Statut === 'EN_ATTENTE' && when(r).isValid && when(r) < weekAgo && !superseded(r); });
const actives = rows.filter(function (r) { return r.Statut !== 'REFUS' && !(r.Statut === 'EN_ATTENTE' && superseded(r)); });
function line(r, extra) { return '- ' + (r.Entreprise || 'Entreprise inconnue') + ' (' + (r.Poste || '?') + ')' + extra; }
return [{ json: {
  semaine: weekAgo.toFormat('dd/MM') + ' au ' + now.toFormat('dd/MM'),
  nb_positifs: positifs.length,
  nb_refus: refus.length,
  nb_relances: relances.length,
  total_actives: actives.length,
  detail_positifs: positifs.map(function (r) { return line(r, r['Prochaine étape'] ? ' : ' + r['Prochaine étape'] : ''); }).join('\n') || 'Aucun',
  detail_relances: relances.map(function (r) { return line(r, ' depuis le ' + when(r).toFormat('dd/MM')); }).join('\n') || 'Aucune'
} }];

